// ---- core: settings, the era table, V3 bridge, helpers, InnerTube ----

// Firefox's add-on build sees the page through Xray wrappers, which hide what V3 keeps on the
// elements (el.data) and the page's own yt object: both are read and written through the page's view.
// (9.0) V3's data is read through an ordinary Xray, not the page's own view: the page's view runs the page's
// Array methods, which may not call back into Gplex ("Permission denied to access object" on map/forEach, which
// left the c3 Videos tab and playlist undrawn in Firefox). Data that is already the page's is written back as it is.
if (window.wrappedJSObject && typeof cloneInto === "function") {
    try {
        Object.defineProperty(HTMLElement.prototype, "data", {
            configurable: true,
            get: function() {
                const w = this.wrappedJSObject;
                const d = w ? w.data : undefined;
                return d && typeof d === "object" ? XPCNativeWrapper(d) : d;
            },
            set: function(v) {
                const w = this.wrappedJSObject;
                if (!w) {
                    return;
                }
                if (v && typeof v === "object") {
                    try {
                        w.data = cloneInto(v, window, { cloneFunctions: true });
                    } catch (e) {
                        w.data = v;
                    }
                } else {
                    w.data = v;
                }
            }
        });
    } catch (e) {}
}
