// (9.0) {{name}} is text (YouTube's titles, names, counts) and is escaped; {{{name}}} is markup the
// caller made (the channel description with its <br>s)
const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" };
function fill(tpl, values) {
    return tpl.replace(/\{\{\{(\w+)\}\}\}|\{\{(\w+)\}\}/g, function(m, raw, k) {
        const v = values[raw || k];
        const s = v === undefined || v === null ? "" : String(v);
        return raw ? s : s.replace(/[&<>"']/g, function(c) {
            return ESCAPES[c];
        });
    });
}

// ---- shell: the attributes the stylesheet keys on, the masthead, the guide, the footer ----

// what the page knows about the visitor and the current page (StarTube's gdp)
const me = { loggedIn: false, name: "", email: "", subs: "", pfp: "", lowPfp: "", channelUrl: "", channelId: "", dark: false };
function body() {
    return $("body .spitfire-body-container");
}
// the page kind, from V3's #page classes and the address
function pageKind() {
    const path = location.pathname;
    if ($("#page.watch")) {
        return "watch";
    }
    if ($("#page.channel")) {
        return "channel";
    }
    if ($("#page.search")) {
        return "search";
    }
    if ($("#page.all_comments")) {
        return "comments";
    }
    if (path === "/playlist") {
        return "playlist";
    }
    if (path.indexOf("/feed/UC") === 0) {
        return "feed-inline-channel";
    }
    if (path.indexOf("/feed/guide") === 0) {
        return "feed-guide-builder";
    }
    if (path.indexOf("/feed/subscriptions") === 0) {
        return "feed-subs";
    }
    if (path.indexOf("/feed/social") === 0) {
        return "feed-social";
    }
    if (path === "/feed/recommended_for_you" || path === "/feed/what_to_watch/recommended") {
        return "feed-recs";
    }
    if (path.indexOf("/feed") === 0) {
        return "feed";
    }
    if ($("#page.home")) {
        return "home";
    }
    return "";
}
// (9.0) the era flags the extra sheets (css/extra, not flattened per era) still read as attributes (2012's
// buttons are keyed on its era, [ly="cosmic2012_1"], as no other era has them)
const FLAG_ATTRIBUTES = { Channels3TimeVisible: "exp-channels3-time-visible", Channels3DateVisible: "exp-channels3-date-visible" };
// the attributes that never change within an era (the flattened stylesheet keys on [st] for them)
// and the ones that do
function setEraAttributes() {
    attr(html, "st", true);
    attr(html, "startube", true);
    attr(html, "ly", ERA.id);
    attr(html, "static", has("StaticSite"));
    attr(html, "nocast", true);
    // (9.0) the period Subscribe buttons outside the watch page (stargazer-header sheet): orange in
    // 2007, yellow in 2008-2009
    attr(html, "cirrus-sub", ERA.header === "tabbed-cirrus");
    attr(html, "stargazer-sub", !!ERA.header && ERA.header !== "tabbed-cirrus");
    Object.keys(FLAG_ATTRIBUTES).forEach(function(flag) {
        attr(html, FLAG_ATTRIBUTES[flag], has(flag));
    });
    attr(html, "stargazer-header", ERA.header || false);
    attr(html, "upload-icon", ERA.upload === "icon");
    attr(html, "create-icon", ERA.upload === "create");
    attr(html, "exp-youtube-apps", ERA.apps === "yt");
    attr(html, "exp-account-menu", !!ERA.account && ERA.account !== "me");
    attr(html, "exp-polymer-account-menu", ERA.account === "poly");
    const b = body();
    if (b) {
        attr(b, "st", true);
        attr(b, "layout", ERA.id);
        attr(b, "rel-size", ERA.relatedSize || "small");
        attr(b, "compact-date", ERA.compactDate ? "on" : "off");
        attr(b, "search-text", ERA.searchText ? "on" : "off");
        attr(b, "poly-layout", FAMILY === "poly" ? "true" : false);
    }
}
// (9.0) 2010-2011 had no guide: only the subscriptions page kept its channel list down the left. 2012's
// was on the home and the feeds (Wayback, June 2012), not on watch, channel or search pages. (9.0) The 2012
// home keeps its guide but, like every 2012 page, has no guide button beside the logo: "home" says so
function guideMode(kind) {
    if (has("NoGuide") || (FAMILY === "aozora" && kind !== "feed-subs")) {
        return "no";
    }
    return has("GuideOnFeedsOnly") ? (kind === "home" ? "home" : "feeds") : false;
}
function setPageAttributes() {
    const kind = pageKind();
    attr(html, "location", kind || false);
    attr(html, "guide", guideMode(kind));
    attr(html, "dark", !!$(".dark-mode"));
    attr(html, "gbar", !!$(".gaiabar"));
    me.dark = !!$(".dark-mode");
    if (kind === "channel") {
        const sub = /\/(feed|videos|playlists|posts|about|search)(\/|$|\?)/.exec(location.pathname);
        attr(html, "chan-loc", sub ? (sub[1] === "posts" ? "backstage" : sub[1]) : "home");
    } else {
        attr(html, "chan-loc", false);
    }
    if (kind === "playlist") {
        const page = /[?&]page=(\d+)/.exec(location.search);
        attr(html, "pl-page", page ? page[1] : "1");
        attr(html, "pl-page-over-10", !!page && Number(page[1]) > 10);
    }
    const b = body();
    if (b && kind === "watch") {
        attr(b, "playlist-watch", /[?&]list=/.test(location.search) ? "true" : "false");
    }
    watchQueue();
    return kind;
}
// (9.0) V3's Watch Queue tray (late 2014 to 2016) shows only in those years, and only with something
// queued, as it did then; the stylesheet hides it without [st-wq]
const WATCH_QUEUE_ERAS = /^hh(E2015|2015|E2016|M2016|2016)$/;
function watchQueue() {
    if (!WATCH_QUEUE_ERAS.test(ERA.id)) {
        return;
    }
    when(".watch-queue-count", function(count) {
        if (count.classList.contains("st-watched")) {
            return;
        }
        count.classList.add("st-watched");
        const update = function() {
            attr(html, "st-wq", Number(count.textContent) > 0);
        };
        new MutationObserver(update).observe(count, { childList: true, characterData: true, subtree: true });
        update();
    });
}
// (9.0) signed out for certain: V3 has drawn its "Sign in" (before V3's user area is drawn, neither is known)
function signedOut() {
    return !!$("#yt-masthead-signin");
}
function readVisitor() {
    const user = $("#yt-masthead-user");
    me.loggedIn = !$("#yt-masthead-signin") && !!user;
    attr(html, "logged-in", me.loggedIn ? "true" : "false");
    if (user) {
        const img = $(".yt-thumb-27 img", user);
        me.lowPfp = img ? img.src : "";
        // (9.0) no picture yet: no "=s108" (a request relative to the page)
        me.pfp = me.lowPfp ? me.lowPfp.split("=s")[0] + "=s108" : "";
        me.name = ($("#yt-masthead-user-displayname") || {}).textContent || "";
    }
    const mine = $(".guide-user-links .guide-channel[id^='UC'] a");
    if (mine) {
        me.channelUrl = mine.getAttribute("href") || "";
        me.channelId = me.channelUrl.split("/channel/")[1] || "";
    }
}

// ---- masthead
const FAVICONS = {
    "2017": "https://www.youtube.com/s/desktop/daa4e47c/img/favicon_32x32.png",
    "2015": "https://s.ytimg.com/yts/img/favicon_32-vfl8NGn4k.png",
    "2010": "https://s.ytimg.com/yt/favicon-vflZlzSbU.ico",
    "2005": "https://s.ytimg.com/yt/favicon-vfl1123.ico"
};
// V3 sets its own 2012 icon; the others are swapped in after it has
function setFavicon() {
    const url = FAVICONS[ERA.favicon];
    if (!url) {
        return;
    }
    let link = $("#st-favi");
    if (!link) {
        const old = $("head [rel='icon']");
        if (!old) {
            return;
        }
        link = old.cloneNode(true);
        link.id = "st-favi";
        old.remove();
        document.head.appendChild(link);
    }
    setTimeout(function() {
        link.href = url;
    }, 3000);
}
// the menus live outside V3's masthead, under a fence that closes them
// (9.0) with the shell's own sheet (css/extra/shell.css: the period footers, the signed-out masthead
// and guide of 2017-2022), which the menus' box carries on every page
function menus() {
    let m = $("#st-menus");
    if (!m) {
        const c = fromHtml('<div id="st-menus-container"><div id="st-menus"></div><div id="st-menus-fence"></div></div>');
        extraStyle("shell", c);
        document.body.insertBefore(c, document.body.firstChild);
        m = $("#st-menus");
        $("#st-menus-fence").addEventListener("click", closeMenus);
        window.addEventListener("click", periodLinkClick, true);
    }
    return m;
}
function closeMenus() {
    const c = $("#st-menus-container");
    if (c) {
        c.classList.remove("menu-visible");
    }
    $$("#st-menus [visible]").forEach(function(el) {
        el.removeAttribute("visible");
    });
    // (9.0) every button toggleMenu marks, the signed-out ⋮ of 2017-2022 too (it kept its grey circle)
    $$("#startube-youtube-apps, #startube-settings-button").forEach(function(button) {
        button.classList.remove("active");
    });
}
function toggleMenu(menu, button) {
    const c = $("#st-menus-container");
    const open = !menu.hasAttribute("visible");
    closeMenus();
    if (open) {
        menu.setAttribute("visible", "");
        c.classList.add("menu-visible");
        if (button) {
            button.classList.add("active");
        }
    }
}
// a parking place for V3 elements moved between pages
function space() {
    let s = $("#st-space");
    if (!s) {
        s = fromHtml('<div id="st-space"></div>');
        document.body.insertBefore(s, document.body.firstChild);
    }
    return s;
}
function svgIcon(filled, outline) {
    const box = fromHtml('<div class="st-svg">' + T.svg + "</div>");
    $(".filled-icon path", box).setAttribute("d", filled);
    $(".outline-icon path", box).setAttribute("d", outline);
    return box;
}
