// (9.0) the signed-out guide of 2013-2022 as the captures have it: Best of YouTube and no list of channels "for
// you", no History before Polymer (2014-2016); from late 2019 the "Sign in to like videos…" box under the first
// section, its button outlined with the signed-out avatar (Wayback, Dec 2019 and June 2022)
function signedOutGuide() {
    if (!signedOut() || (FAMILY !== "hh" && FAMILY !== "poly")) {
        return;
    }
    $$("#guide-subscriptions-section").forEach(function(section, n) {
        section.style.display = n > 0 ? "none" : "";
    });
    // Best of YouTube whole: V3's "More ›" fold (2013-early 2015; the later guides unfold in scrollableGuide)
    const list = $("#guide-subscriptions-section #guide-channels");
    const more = list && !has("TrueScrollableGuide") && list.parentNode.querySelector(".guide-flyout-container");
    if (more) {
        $$(".overflow-list > li", more).forEach(function(item) {
            list.appendChild(item);
        });
        more.style.display = "none";
    }
    const history = $("#FEhistory-guide-item");
    if (history && FAMILY === "hh") {
        history.style.display = "none";
    }
    const promo = $(".guide-section.signup-promo");
    if (!promo || FAMILY !== "poly" || Number(ERA.year) < 2019 || promo.classList.contains("st-promo-2019")) {
        return;
    }
    promo.classList.add("st-promo-2019");
    text("p .run", "Sign in to like videos, comment, and subscribe.", promo);
    const button = $("#guide-builder-promo-buttons a", promo);
    if (button) {
        button.insertBefore(fromHtml(T.signInAvatar), button.firstChild);
        button.classList.add("st-signin-outlined");
    }
    const first = $(".guide-toplevel > .guide-section");
    if (first && first !== promo) {
        first.parentNode.insertBefore(promo, first.nextSibling);
    }
}
// 2007-2012: "Browse Channels", the profile block and the From YouTube entry at the top of the guide
