function polyGuideMore() {
    const toplevel = $(".guide-toplevel");
    if (!toplevel || !$("#FEguide_builder-guide-item") || $("#st-guide-more")) {
        return;
    }
    const sections = [fromHtml(T.guideMoreSection), fromHtml(T.guideMoreSection)];
    sections[0].id = "st-guide-more";
    let at = 0;
    GUIDE_MORE.forEach(function(entry) {
        if (!entry) {
            at = 1;
            return;
        }
        const item = fromHtml(fill(T.guideMoreItem, { name: entry[0], href: entry[1] || "#" }));
        const icon = svgIcon(entry[2], entry[2]);
        icon.classList.add("thumb");
        $(".yt-valign-container", item).insertBefore(icon, $(".yt-valign-container", item).firstChild);
        if (entry[3]) {
            v3Link($("a", item), "browse", entry[3]);
        }
        if (!entry[1]) {
            $("a", item).addEventListener("click", function(e) {
                e.preventDefault();
                openV3Settings();
            });
        }
        $("ul", sections[at]).appendChild(item);
    });
    $("h3", sections[1]).remove();
    sections.forEach(function(section) {
        toplevel.insertBefore(section, $("#startube-guide-footer"));
    });
}
// the fixed-width ("static") site of 2007-2012: the guide sits where the content starts
function placeGuide() {
    const content = $("#content");
    const menu = $("[static] #appbar-guide-menu");
    if (!content || !menu) {
        return;
    }
    // (9.0) the page's own height, not the one an earlier call gave it
    content.style.minHeight = "";
    const box = content.getBoundingClientRect();
    menu.style.left = box.left + "px";
    html.style.setProperty("--guide-left", box.left + "px");
    const mh = $("#masthead-positioner");
    if (mh) {
        const top = mh.getBoundingClientRect().height;
        menu.style.top = top + "px";
        html.style.setProperty("--guide-top", top + "px");
    }
    // (9.0) a guide longer than the page (2012 signed out, with its "Sign in" box) makes the page as
    // long as itself instead of scrolling inside a cut-off column. Its length is that of what it holds:
    // the menu itself stretches to the page (top and bottom 0), so its own height is the page's
    html.style.setProperty("--guide-height", "auto");
    menu.style.maxHeight = "none";
    const natural = Array.prototype.reduce.call(menu.children, function(sum, child) {
        return sum + child.offsetHeight;
    }, 0);
    content.style.minHeight = natural > box.height - 20 ? (natural + 20) + "px" : "";
    const height = Math.max(box.height - 20, natural) + "px";
    menu.style.height = height;
    html.style.setProperty("--guide-height", height);
}

// ---- footer
// (9.0) the copyright line of the era's year, never today's: "YouTube, LLC" from mid-2007 (the earliest
// era, the Aug-Oct 2007 page the 1997-2006 layouts draw), "Google LLC" from 2020 (Wayback, each year's
// home page)
function copyrightLine() {
    const year = Number(ERA.year);
    return "© " + year + (year < 2020 ? " YouTube, LLC" : " Google LLC");
}
// the pickers of V3's footer as each year worded them (Wayback home pages: "Location" and "Safety" in
// 2012, "Country" from late 2013, "Restricted Mode" from 2016, "Content location" in late 2016); no
// "Dark Theme" before 2017
const FOOTER_PICKERS = [
    ["#yt-picker-country-button .run", function(y) {
        return y < 2013 ? "Location:" : ERA.id === "hh2016" ? "Content location:" : "Country:";
    }],
    ["#yt-picker-safetymode-button .run", function(y) {
        return y < 2016 ? "Safety:" : "Restricted Mode:";
    }]
];
// (9.0) 2007-2010: the era's own footer over V3's (T.periodFooters); its picker links open V3's pickers,
// which move into it
function periodFooter() {
    const markup = T.periodFooters[ERA.id];
    const container = $("#footer-container");
    if (!markup || !container || $("#st-pf")) {
        return !!markup;
    }
    const foot = fromHtml(fill(markup, { copyright: copyrightLine() }));
    container.classList.add("st-pf-on");
    container.appendChild(foot);
    const panels = $(".st-pf-picker-panels", foot);
    $$("[st-pf-picker]", foot).forEach(function(a) {
        const name = a.getAttribute("st-pf-picker");
        move($("#yt-picker-" + name + "-footer"), panels);
        a.href = "#";
        a.addEventListener("click", function(e) {
            e.preventDefault();
            const button = $("#yt-picker-" + name + "-button");
            if (button) {
                button.click();
            }
        });
    });
    $$("[st-pf-value]", foot).forEach(function(el) {
        const run = $("#yt-picker-" + el.getAttribute("st-pf-value") + "-button .run");
        el.textContent = run ? run.textContent.replace(/^[^:]*:/, "").trim() : "";
    });
    return true;
}
// V3's footer in the era's words: its copyright line and pickers
function footerYear() {
    if (periodFooter()) {
        return;
    }
    const links = $("#footer-links-secondary");
    if (links && !$("#st-yt-c")) {
        const c = fromHtml('<li id="st-yt-c"><span class="copyright" dir="ltr"></span></li>');
        $(".copyright", c).textContent = copyrightLine();
        links.appendChild(c);
    }
    const year = Number(ERA.year);
    FOOTER_PICKERS.forEach(function(p) {
        const run = $(p[0]);
        if (run && !run.classList.contains("st-worded")) {
            run.textContent = run.textContent.replace(/^\s*[^:]+:/, " " + p[1](year));
            run.classList.add("st-worded");
        }
    });
    $$(".pickers li").forEach(function(li) {
        if (/Dark Theme/.test(li.textContent)) {
            li.style.display = "none";
        }
    });
    footerExtras();
}
// (9.0) what the 2013-2016 footers had beyond V3's (Wayback: Help from June 2013, +YouTube from June 2014, History
// from Dec 2014; "Press", "Creators" and "Advertise" from Feb 2015, drawn from hh2015: Early 2015 keeps the long
// names of Dec 2014 and Jan 2015)
const FOOTER_EXTRAS = { footerHelp: ["hh2013_1", "hh2016"], footerHistory: ["hhE2015", "hh2016"], footerPlus: ["hh2014", "hh2016"] };
const FOOTER_SHORT_NAMES = { "Press & Blogs": "Press", "Creators & Partners": "Creators", "Advertising": "Advertise" };
function footerExtras() {
    const pickers = $("#footer-main .pickers");
    const developers = $("#footer-links-primary li:last-child");
    if (FAMILY !== "hh" || !pickers || !developers || $(".st-footer-extra")) {
        return;
    }
    ["footerHelp", "footerHistory"].forEach(function(name) {
        if (eraIn(FOOTER_EXTRAS[name])) {
            pickers.parentNode.insertBefore(fromHtml(T[name]), pickers.nextSibling);
        }
    });
    if (eraIn(FOOTER_EXTRAS.footerPlus)) {
        developers.parentNode.appendChild(fromHtml(T.footerPlus));
    }
    if (eraIn(["hh2015", ""])) {
        $$("#footer-links-primary a").forEach(function(a) {
            a.textContent = FOOTER_SHORT_NAMES[a.textContent.trim()] || a.textContent;
        });
    }
}

// ---- watch page: the period's rows around V3's player, filled from what V3 knows and from YouTube ----

// what the page knows about the video (StarTube's CWD), reset on each navigation
let video = {};
function watchId() {
    const m = /[?&]v=([^&]+)/.exec(location.search) || /\/shorts\/([^/?&]+)/.exec(location.pathname);
    return m ? m[1] : "";
}
const WATCH_WL = { watch3: "w3", watch4a: "w4a", watch4b: "w4b", watch5a: "w5a", watch5b: "w5b", watch5c: "w5c", watch5d: "w5d", watch7: "w7",
    watch8: "w8", watch9a: "w9a", watch9b: "w9b", watch9c: "w9c", watch10beta: "w10beta" };
const TITLE_ON_TOP = /^watch[345]/;
const VIDEO_DROPDOWN = /^watch5[acd]$/;
const OLD_LOOK = /^watch[345]/;

// ---- the rows
function buildWatch() {
    const content = $("#watch7-content.watch-content");
    const sidebar = $("#watch7-sidebar-contents");
    if (!content || !sidebar || $("#st-watch-below-container")) {
        return;
    }
    const wl = ERA.watch;
    const at = $("#watch7-creator-bar") ? 1 : 0;
    const container = function(id, cls, markup) {
        return fromHtml('<div id="' + id + '" class="' + cls + " " + wl + '" wl="' + wl + '">' + markup + "</div>");
    };
    content.insertBefore(container("st-watch-below-container", "stdustwb", T.watchBelow), content.children[at]);
    content.insertBefore(container("st-watch-above-container", "stdustwa", T.watchAbove), content.children[at]);
    sidebar.insertBefore(container("st-watch-side-container", "stdustws", T.watchSide), sidebar.firstChild);
    sidebar.classList.add(wl);
    const put = function(holder, row) {
        setHtml($("#st-" + holder + "-row-holder"), T.rows[row]);
    };
    if (TITLE_ON_TOP.test(wl)) {
        put("above-title", "aboveTitle");
    } else if (wl !== "watch7") {
        put("below-title", "belowTitle");
    }
    if (/^watch4/.test(wl)) {
        put("ratings-info", "ratingsInfo");
        put("watch-tabs", "watchTabs");
        put("side-banner", "sideBanner");
        put("side-owner", "sideOwner");
        put("side-desc", "sideDesc");
        put("side-panels", "sidePanels");
        $("#st-watch-below").setAttribute("state", "share");
    }
    if (VIDEO_DROPDOWN.test(wl)) {
        put("above-owner", "aboveOwner");
        put("above-videos", "aboveVideos");
        put("actions-info", "actionsInfo");
        put("panels", "panels");
        put("desc", "desc");
        wireVideoDropdown();
    }
    if (wl === "watch8") {
        put("owner-info", "ownerInfo");
        put("actions", "actions");
        put("panels", "panels");
        put("desc", "desc");
        put("floaters", "floaters");
        put("extras", "extras");
    }
    if (wl === "watch9a") {
        put("info-actions", "infoActions");
        put("owner", "owner");
        put("desc", "desc");
        put("floaters", "floaters");
        put("extras", "extras");
        put("side-panels", "sidePanels");
        laterPopups();
    }
    if (wl === "watch10beta") {
        put("desc-actions", "descActions");
        put("owner-teaser", "ownerTeaser");
        put("floaters", "floaters");
        put("extras", "extras");
        put("side-panels", "sidePanels");
        laterPopups();
    }
    if (TITLE_ON_TOP.test(wl)) {
        setTimeout(topHeight, 1000);
    }
    moveWatchElements();
    wireWatchActions();
    if (FAMILY === "cosmic") {
        const toggle = $("#watch-description-toggle");
        if (toggle) {
            const rule = fromHtml('<div id="watch5-horizontal-rule">' + T.horizontalRule + "</div>");
            toggle.insertBefore(rule, toggle.firstChild);
        }
        when("#watch7-sidebar", function(sb) {
            if (!$("#sidebar-panda-rules")) {
                sb.insertBefore(fromHtml('<div id="sidebar-panda-rules">' + T.verticalRules + "</div>"), sb.firstChild);
            }
        });
    }
    if (wl === "watch5d") {
        $$(".st-btn").forEach(function(b) {
            b.classList.add("yt-uix-button", "yt-uix-button-default", "yt-uix-button-size-default");
        });
    }
    if (/^watch5[abc]$/.test(wl)) {
        $$(".st-btn").forEach(function(b) {
            b.classList.add("aozora-button");
        });
    }
    subscribeButtonStyle();
}
function topHeight() {
    const above = $("#st-watch-above");
    if (above) {
        body().style.setProperty("--top-title-height", above.offsetHeight + "px");
    }
}
// the subscribe button takes the period's shape (the stylesheet draws each class). (9.0) As 8.47: Mid 2013 keeps
