    const kind = passStep(setPageAttributes);
    passStep(readVisitor);
    // (9.0) on every page, not the home's alone: the mark homeRedirect falls back on
    passStep(noteSignIn);
    passStep(menus);
    passStep(space);
    if (fresh) {
        passStep(closeMenus);
        passStep(commentPanelClosed);
    }
    passStep(footerYear);
    passStep(masthead);
    passStep(guide);
    passStep(stargazerTab, kind);
    if (Object.prototype.hasOwnProperty.call(PAGE_STEPS, kind)) {
        PAGE_STEPS[kind](fresh);
    } else {
        passStep(feedAsHome);
        passStep(homePage, kind);
    }
