function ugfWorkspaceSite() {
    const m = /^\/(?:intl\/[^/]+(?:\/|$))?(.*?)(?:\.html)?\/?$/.exec(window.location.pathname || "/");
    if (window.location.host !== "workspace.google.com" || window.top !== window.self || !m) {
        return false;
    }
    // (8.38) Gmail's about page is the Gmail setting's (ugfGmailAbout), and what it kept stays
    if (m[1] === "gmail" && ugfWsValue("UGF_GMAIL_ON", "true") !== "false") {
        return false;
    }
    // with the setting off what was kept goes as well, and (8.37) so do the pages an 8.36 add-on kept, as the add-on now keeps none
    const off = ugfWsValue("UGF_WORKSPACE_ON", "true") === "false";
    if (off || typeof GM_gplexPage === "function") {
        try {
            window.caches.keys().then(function(names) {
                names.forEach(function(n) {
                    if (/^gplex-ws-/.test(n)) {
                        window.caches.delete(n);
                    }
                });
            }).catch(function() {});
        } catch (e) {}
    }
    // (only with the setting off: the note of a failure below has to last, or a page that can't be had would reload for ever)
    if (off) {
        try {
            Object.keys(window.localStorage).forEach(function(k) {
                if (/^ugf_ws_/.test(k)) {
                    window.localStorage.removeItem(k);
                }
            });
        } catch (e) {}
        return false;
    }
    // (8.41) Google Voice signed out, where voice.google.com sends it, is ugfVoiceAbout's (today's page with the chrome if it shows none)
    if (m[1] === "products/voice") {
        return ugfVoiceAbout();
    }
    const slug = m[1].replace(/\//g, "-");
    const L = ugfSharedLayout(ugfWsValue);
    const file = slug || "home";
    if (slug === "home" || slug === "common") {
        return false;
    }
    // (8.41) Meet's page, where signed-out meet.google.com goes, is its earliest (Hangouts' of December 2014) before 2015
    const own = ugfWorkspaceEra(L);
    const era = file === "products-meet" && own && !Object.prototype.hasOwnProperty.call(UGF_WS_PAGES[own], file) ? "w2015" : own;
    // the 2012 page also serves Late 2011-Early 2012, before the blue icon of August 2012
    return ugfStoredSite(era, file, { mark: "gplex-ws-site", ready: ugfWsControls, icon: function(P, fill) {
        const icon = era === "b2012" && /^201[12]$/.test(L) ? "2010" : P.icon;
        return UGF_PRODUCTS._icons[icon] || fill(icon);
    } });
}
function ugfWorkspaceYears() {
    const from = UGF_WS_FROM[window.location.host];
    if (!from || window.top !== window.self || ugfWsValue("UGF_WORKSPACE_ON", "true") === "false") {
        return;
    }
    const L = ugfSharedLayout(ugfWsValue);
    const m = L.match(/(19|20)\d\d/);
    const y = m ? parseInt(m[0], 10) : 0;
    if (y < from || y >= 2022) {
        return;
    }
    const era = y <= 2008 ? "w06" : y <= 2010 ? "w09" : y <= 2012 ? "w11" : y <= 2014 ? "w13" : y <= 2017 ? "w15" : y <= 2019 ? "w18" : "w20";
    const h = document.documentElement;
    h.setAttribute("gplex-ws", era);
    const st = document.createElement("style");
    st.id = "ugf-ws-css";
    st.textContent = UGF_WS_CSS;
    (document.head || h).appendChild(st);
    console.log("[Gplex] " + window.location.host + ": the chrome of " + L + " (" + era + ")");
}
if (UGF_WS_FROM[window.location.host] && !ugfWorkspaceSite()) {
    ugfWorkspaceYears();
}
