        const logo = { a: UGF_M_ASSETS.logoA, b1: UGF_M_ASSETS.logoB, b2: UGF_M_ASSETS.logoB, c: UGF_M_ASSETS.logoC, d: UGF_M_ASSETS.logoD }[era];
        const vert = ugfMobileVertical();
