    // the pieces of today's knowledge panel (the head over the results, the overview beside them)
    function ugfKpParts() {
        const parts = Array.prototype.filter.call(document.querySelectorAll(".kp-wholepage-osrp"), function(e) {
            return !ugfNeuroMine(e) && !e.parentElement.closest(".kp-wholepage-osrp");
        });
        return parts.some(function(e) {
            return e.querySelector('[data-attrid="title"]');
        }) ? parts : [];
    }
    function doSidebar(mode) {
        if (mode == 3) {
            const list = [];
            ugfKpParts().forEach(function(part) {
                part.querySelectorAll("[data-attrid]").forEach(function(e) {
                    if (list.indexOf(e) < 0 && !e.closest(".related-question-pair")) {
                        list.push(e);
                    }
                });
            });
            tempSidebarList = list;
        } else if (
            mode == 2 &&
            document.querySelectorAll('[role="complementary"]')[2]
        ) {
            tempSidebarList = document.querySelectorAll('[role="complementary"]')[2].querySelectorAll("[data-attrid]");
        } else {
            tempSidebarList = document.querySelector('[role="complementary"]').querySelectorAll("[data-attrid]");
        }
        let sidebarTitle;
        let sidebarSubtitle = "";
        let sbImg = "";
        let sbDesc = "";
        const sbKcs = [];
        tempSidebarList.forEach(itemRoot => {
            var itemId = itemRoot.getAttribute("data-attrid");
            if (itemId == "title" && !sidebarTitle) {
                sidebarTitle = mode == 3 ? ugfEscapeHtml(String(itemRoot.textContent || "").trim()) : itemRoot.innerHTML;
            }
            if (itemId == "subtitle" && !sidebarSubtitle) {
                const sub = String(itemRoot.textContent || "").replace(/\s+/g, " ").trim();
                // (8.5) a product's stars and their count ("(7.1K)") came in 2017; before that the line said what the thing was
                if (!(mode == 3 && ugfKpEra() === "k" && /^[\d.,]*\s*(?:\u2605+|stars?)?\s*\(?[\d.,]+[KkMm]?\)?$/.test(sub))) {
                    sidebarSubtitle = mode == 3 ? ugfEscapeHtml(sub) : itemRoot.innerHTML;
                }
            }
            if ((itemId == "image" || itemId == "VisualDigestFirstImageResult") && !sbImg && itemRoot.querySelector("img")) {
                const im = itemRoot.querySelector("img");
                let src = im.getAttribute("src") || "";
                if ((!src || /^data:image\/gif/.test(src) || src.length < 100 && /^data:/.test(src)) && im.id) {
                    src = ugfGetDeferredImage(im.id) || im.getAttribute("data-src") || src;
                }
                sbImg = src;
            }
            if (
                itemId == "description" && !sbDesc
            ) {
                if (mode == 3) {
                    const d = itemRoot.cloneNode(true);
                    d.querySelectorAll("h1, h2, h3, [role='heading']").forEach(function(h) {
                        h.remove();
                    });
                    sbDesc = d.innerHTML;
                } else {
                    sbDesc = itemRoot.innerHTML;
                }
            }
            /*if (
                document.querySelector("[data-attrid='description']")
               ) {
                sbDesc = document.querySelector("[data-attrid='description']").innerHTML;
            }*/
            if (
                !itemId.includes("kc:/ugc:user_reviews") &&
                !itemId.includes("kc:/film/film:media_actions_wholepage") &&
                !itemId.includes("kc:/ugc:thumbs_up") &&
                itemId.includes("kc:/") ||
                itemId.includes("ss:/")
            ) {
                if (sbKcs.length < 12) {
                    sbKcs.push(itemRoot.innerHTML);
                }
            }
        });
        if (mode == 2) {
            tempUpbarList.forEach(itemRoot => {
                var itemId = itemRoot.getAttribute("data-attrid");
                if (itemId == "title") {
                    sidebarTitle = itemRoot.textContent;
                }
                if (itemId == "subtitle") {
                    sidebarSubtitle = itemRoot.textContent;
                }
            });
        }
        // (today's picture strip sits outside the panel's parts)
        if (mode == 3 && !sbImg) {
            const im = document.querySelector('[data-attrid="VisualDigestFirstImageResult"] img, [data-attrid="image"] img');
            if (im && !ugfNeuroMine(im)) {
                let src = im.getAttribute("src") || "";
                if ((!src || /^data:image\/gif/.test(src) || src.length < 100 && /^data:/.test(src)) && im.id) {
                    src = ugfGetDeferredImage(im.id) || im.getAttribute("data-src") || src;
                }
                sbImg = src;
            }
        }
        // (8.0) the panel's other pictures, for the collage of 2012-2016
        const sbImgs = [];
        if (mode == 3) {
            ugfKpParts().forEach(function(part) {
                part.querySelectorAll("[data-attrid] img").forEach(function(im) {
                    const at = im.closest("[data-attrid]").getAttribute("data-attrid") || "";
                    if (!/image/i.test(at) || /^(kc|ss):\//.test(at) || ugfNeuroMine(im) || sbImgs.length >= 5) {
                        return;
                    }
                    let src = im.getAttribute("src") || "";
                    if ((!src || /^data:image\/gif/.test(src) || src.length < 100 && /^data:/.test(src)) && im.id) {
                        src = ugfGetDeferredImage(im.id) || im.getAttribute("data-src") || src;
                    }
                    if (src && !/^data:image\/gif/.test(src) && !(src.length < 100 && /^data:/.test(src)) && sbImgs.indexOf(src) < 0) {
                        sbImgs.push(src);
                    }
                });
            });
            if (sbImg && sbImgs.indexOf(sbImg) > 0) {
                sbImgs.splice(sbImgs.indexOf(sbImg), 1);
                sbImgs.unshift(sbImg);
            }
        }
        if (!sidebarTitle || sidebarTitle.includes("See results about")) {

        } else {
            SB = new SearchSidebarAPI(sidebarTitle, sidebarSubtitle, sbImg, sbDesc, sbKcs);
            SB.imgs = sbImgs;
            if (document.querySelector("#ugf-right-inner")) {
                createSidebar();
            } else {
                var elm = "#ugf-right-inner";
                waitForElement(elm, 10).then(function(elm) {
                    if (canGo != false) {
                        createSidebar();
                    }
                });
            }
        }
    }
