                if (ic.closest("svg") && ic.closest("svg") !== ic) {
                    return;
                }
                const r = ic.getBoundingClientRect();
                const w = parseInt(ic.getAttribute("width"), 10) || Math.round(r.width) || 20;
                const h = parseInt(ic.getAttribute("height"), 10) || Math.round(r.height) || w;
                const bird = document.createElement("img");
                bird.src = UGF_TWITTER_BIRD;
                bird.alt = "Twitter";
                bird.className = (ic.getAttribute("class") || "") + " ugf-twitter-bird";
                bird.width = Math.min(w, h);
                bird.height = Math.min(w, h);
                bird.style.cssText = "width:" + Math.min(w, h) + "px;height:" + Math.min(w, h) + "px;object-fit:contain;border-radius:0;background:none";
