    // (8.39) "1:19 pm (0 minutes ago)", or "Apr 6 (3 days ago)", as the classic conversation dated a message
    function ugfGmailClassicWhen(text) {
        // (8.39) only a date with its year and an English month name: without a year the browser guesses 2001, and
        // a numeric one ("07/11/2026") would be read month first
        const s = String(text || "");
        if (!/\b(19|20)\d{2}\b/.test(s) || !/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/i.test(s)) {
            return text;
        }
        const d = new Date(s.replace(/,(\s*\d{1,2}:\d{2})/, "$1").replace(/\s+at\s+/, " "));
        if (isNaN(d.getTime())) {
            return text;
        }
        const mins = Math.max(0, Math.round((Date.now() - d.getTime()) / 60000));
        const ago = mins < 60 ? mins + " minute" + (mins === 1 ? "" : "s")
            : (mins < 1440 ? Math.round(mins / 60) + " hour" + (Math.round(mins / 60) === 1 ? "" : "s")
                : Math.round(mins / 1440) + " day" + (Math.round(mins / 1440) === 1 ? "" : "s"));
        const day = new Date().toDateString() === d.toDateString()
            ? ((d.getHours() % 12) || 12) + ":" + String(d.getMinutes()).padStart(2, "0") + (d.getHours() < 12 ? " am" : " pm")
            : ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][d.getMonth()] + " " + d.getDate() +
              (d.getFullYear() === new Date().getFullYear() ? "" : ", " + d.getFullYear());
        return day + " (" + ago + " ago)";
    }
    // (8.39) chat in the left column as each period drew it: 2006's blue Quick Contacts box, the blue Chat box and
