            add("#docs-menubar .menu-button.goog-control-hover, #docs-menubar .menu-button.goog-control-open, #docs-menubar #docs-edit-menu", "background: #c3d8fe !important; color: #000 !important;");
            add("#docs-menubar #docs-file-menu", "background: linear-gradient(#fff, #ddd) !important; border: 1px solid #aaa !important; border-radius: 2px !important; color: #333 !important; font: 12px Arial, sans-serif !important; padding: 2px 5px !important; margin: 0 8px 4px 0 !important;");
            add("#docs-menubar #docs-file-menu::after", "content: ''; display: inline-block; margin: 0 0 2px 5px; border-style: solid; border-width: 4px 3px 0; border-color: #777 transparent;");
