        const P = 'html[gplex-docs="' + era + '"][gplex-docs-app="' + (app === "drawings" ? "drawings" : "slides") + '"]';
        // (8.39) Slides' own pictures, cut from Google's screenshots of the time: 2008's links, 2013's corner tile, and the
        // slideshow icon of 2019's Present
        const UGF_839_SLIDES_EDITOR_ART = { newSlide: "data:image/png;base64,", theme: "data:image/png;base64,",
            present: "data:image/png;base64,", tile: "data:image/png;base64,", slideshow: "data:image/svg+xml;base64," };
        const ART = UGF_839_SLIDES_EDITOR_ART;
        const slides = app !== "drawings";
        const lay = String(layout || "");
        // "Start presentation" (one button, no drop-down) until "Present" in 2013
        const start = era === "d2007" || era === "d2009" || era === "d2010" || (era === "d2011" && (lay === "2011" || lay === "2012"));
        // (8.39) late 2011 to mid 2013 (layouts 2011 and 2012), before the look of 30 September 2013 that layouts 2013 and 2013L draw
        const red = era === "d2011" && lay !== "2013" && lay !== "2013L";
        const old = era === "d2007" || era === "d2009";
        const kennedy = era === "d2011" || era === "d2014";
        const material = era === "d2017" || era === "d2019";
        const gm = era === "d2019";
        const font = material ? "Roboto, RobotoDraft, Helvetica, Arial, sans-serif" : "Arial, sans-serif";
        const css = [];
        const add = function(sel, body) {
            css.push(sel.split(",").map(function(x) {
                return P + " " + x.trim();
            }).join(", ") + " { " + body + " }");
        };
