                add(".punch-start-presentation-container", "border: 0 !important; border-radius: 4px !important; box-shadow: none !important; background: transparent !important;");
                add("#punch-start-presentation-left, #punch-start-presentation-right", "background: #fff !important; border: 1px solid #dadce0 !important; box-shadow: none !important; height: 36px !important; box-sizing: border-box !important; color: #3c4043 !important; font: 500 14px 'Google Sans', Roboto, Arial, sans-serif !important;");
                add("#punch-start-presentation-left", "border-radius: 4px 0 0 4px !important; padding: 0 16px 0 12px !important; display: inline-flex !important; align-items: center !important;");
                add("#punch-start-presentation-left::before", "content: ''; width: 24px; height: 24px; margin-right: 8px; background: url(" + ART.slideshow + ") no-repeat center;");
                add("#punch-start-presentation-left .docs-icon, #punch-start-presentation-left .punch-start-presentation-icon", "display: none !important;");
                add("#punch-start-presentation-right", "border-radius: 0 4px 4px 0 !important; margin-left: -1px !important; width: 28px !important; min-width: 0 !important; padding: 0 !important;");
                add("#punch-start-presentation-right .goog-flat-menu-button-dropdown", "border-width: 5px 4px 0 !important; border-color: #5f6368 transparent !important; top: 15px !important; right: 9px !important;");
                add("#docs-titlebar-share-client-button .jfk-button", "background: #fbbc04 !important; color: #202124 !important; border-radius: 4px !important;");
                add("#docs-titlebar-share-client-button .scb-button-icon", "filter: none !important;");
                add("#workspace-container, .two-panel-layout, #speakernotes-dragger", "background: #f8f9fa !important;");
