        add(".punch-filmstrip-scroll", "border-right: 1px solid " + (old ? "#c3d9ff" : red ? "#e5e5e5" : "#ccc") + " !important;");
        add(".punch-filmstrip-thumbnail-background, .punch-filmstrip-thumbnail-border, .punch-filmstrip-thumbnail-border-inner, .punch-filmstrip-thumbnail-drag-overlay, #filmstrip clipPath rect, #pages clipPath rect", "rx: 0 !important; ry: 0 !important;");
        add(".punch-filmstrip-thumbnail-border", "stroke: " + (old ? "#c3d9ff" : era === "d2011" ? "#ddd" : era === "d2014" ? "#dfdfdf" : "#bbb") + " !important; stroke-width: " + (era === "d2014" ? "2px" : "1px") + " !important;");
        // (8.39) the slide you are on: gold on a pale yellow row (2007-2009), a pale yellow row (2010), blue (2011-2017, on a grey
