        const menuGone = { d2009: "#docs-view-menu, #docs-format-menu, #docs-tools-menu", d2010: "#docs-arrange-menu, #docs-tools-menu" }[era] ||
            (era === "d2011" && (lay === "2011" || lay === "2012") ? "#docs-tools-menu" : era === "d2014" && lay !== "2017" && lay !== "2018" ? "#docs-extensions-menu" : "");
