            add("#newSlideButton.goog-toolbar-button-hover, #newSlideMenuButton.goog-toolbar-menu-button-hover", "background: linear-gradient(#dd4b39, #c53727) !important; border-color: #b0281a !important;");
            // its white "+" (8 pixels, 2 thick) and a pale arrow
