        const talk = era !== "gt07" ? "" : ["2009", "2009L"].indexOf(l) > -1 ? "2009" : ["2010", "2010N"].indexOf(l) > -1 ? "2010" : ["2011", "2012"].indexOf(l) > -1 ? "2011" : "2007";
