            '.layers19 { left: 16px; bottom: 26px; width: 74px; height: 74px; border: 2px solid #fff; border-radius: 8px; box-shadow: 0 1px 4px rgba(0,0,0,.3); cursor: pointer; overflow: hidden; }',
            '#ugf-maps-card { display: none; position: absolute; left: 50%; bottom: 21px; width: 384px; height: 72px; margin-left: -192px; background: #fff; border-radius: 2px; box-shadow: 0 1px 4px rgba(0,0,0,.3); z-index: 9; }',
            '#ugf-maps-card.on { display: block; }',
            '#ugf-maps-card .thumb { position: absolute; left: 3px; top: 4px; width: 96px; height: 64px; background-size: cover; background-position: center; cursor: pointer; }',
            '#ugf-maps-card .txt { position: absolute; left: 114px; top: 11px; right: 70px; }',
